mapper.select:
select * from pro_yt_product_specification_supplier
where specification_id=#{specificationId}
and supplier_id=#{supplierId} and is_deleted=0

mapper.insert:
INSERT INTO pro_yt_product_specification_supplier (
    supplier_id, specification_id, create_user, create_time,supplier_specification,min_number,supplier_price,
update_user, update_time, tenant_id, is_deleted,supplier_specification_code
) VALUES

    (
        #{item.supplierId}, #{item.specificationId}, #{item.createUser}, #{item.createTime},#{item.supplierSpecification},#{item.minNumber},#{item.supplierPrice},
    #{item.updateUser}, #{item.updateTime}, #{item.tenantId}, #{item.isDeleted}, #{item.supplierSpecificationCode}
    )

mapper.select:
SELECT pys.id as supplierId, pys.name as supplierName FROM pur_yt_supplier as pys LEFT JOIN pro_yt_product_specification_supplier as pypss ON pys.id = pypss.supplier_id WHERE pypss.is_deleted = 0
AND pypss.specification_id IN
#{specificationId}
GROUP BY pys.id, pys.name
HAVING COUNT(DISTINCT pypss.specification_id) = ${specificationIds.size()}

SELECT p.id, p.supplier_id, p.specification_id, p.supplier_specification, p.min_number, p.supplier_price, ps.name as supplierName, ps.code as supplierCode, p.supplier_specification_code, (select code from pro_yt_product where id=(select product_id from pro_yt_product_specification where id=p.specification_id)) as productCode FROM pro_yt_product_specification_supplier p LEFT JOIN pur_yt_supplier ps ON p.supplier_id = ps.id WHERE p.supplier_id = #{supplierId} AND p.is_deleted = 0
AND p.specification_id in (select id from pro_yt_product_specification where product_id in (select id from pro_yt_product where code like concat('%',#{productCode},'%')))
AND p.specification_id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{specificationName}, '%')))
AND p.specification_id = #{specificationId}
AND p.supplier_specification LIKE CONCAT('%', #{supplierSpecification}, '%')
AND p.min_number = #{minNumber}
AND p.supplier_specification_code like concat('%',#{supplierSpecificationCode},'%')
AND p.supplier_price = #{supplierPrice}
